public class Main {
    public static void main(String[] args) {
        Thermostat t = new Thermostat();
        System.out.println("Start: " + t.getTemperature());
        t.setTemperature(24);
        System.out.println("Set 24: " + t.getTemperature());
        t.setTemperature(35);
        System.out.println("Set 35: " + t.getTemperature());
        t.setTemperature(5);
        System.out.println("Set 5: " + t.getTemperature());
    }
}

class Thermostat {
    private int temperature = 20;

    public int getTemperature() {
        return temperature;
    }

    public void setTemperature(int temperature) {
        if (temperature >= 10 && temperature <= 30) {
            this.temperature = temperature;
        }
    }
}

