public class Main {
    public static void main(String[] args) {
        Direction start = Direction.valueOf("NORTH");
        Direction facing = start;
        for (int i = 1; i <= 4; i++) {
            Direction next = turnRight(facing);
            System.out.println("Turn " + i + ": " + facing.name() + " (" + facing.getDegrees() + ") -> "
                    + next.name() + " (" + next.getDegrees() + ")");
            facing = next;
        }
        System.out.println("Back at start: " + (facing == start));
    }

    static Direction turnRight(Direction d) {
        return switch (d) {
            case NORTH -> Direction.EAST;
            case EAST -> Direction.SOUTH;
            case SOUTH -> Direction.WEST;
            case WEST -> Direction.NORTH;
        };
    }
}

enum Direction {
    NORTH(0), EAST(90), SOUTH(180), WEST(270);

    private final int degrees;

    Direction(int degrees) {
        this.degrees = degrees;
    }

    public int getDegrees() {
        return degrees;
    }
}
